constraints:
1 <= N <= 10^{5}

expected time complexity: O(LogN)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def getSpecialNumber(self, n):
		digits = []
		n -= 1
		while n:
			digits.append(n % 6)
			n //= 6
		ans = 0
		for d in reversed(digits):
			ans = ans * 10 + d
		return ans
